import React from 'react';
import { createRoot } from 'react-dom/client';
import { RepositoryChanges } from '../../client/src/components/RepositoryChanges';
import type { RepositoryChange, RepositoryOverview, RepositoryReleaseMode } from '../../shared/repository-releases';
import '../../client/src/styles/globals.css';
const row=(id:string,title:string,state:RepositoryChange['state'],file:string):RepositoryChange=>({id,taskId:id,title,state,projectId:'fixture',profileId:'default',reason:state==='ready'?'Checked and combined with the other accepted changes.':state==='stopped'?'Work is saved. Finish this task and pass its checks before publishing these changes.':'This task is still working. Its changes are saved.',changedFiles:[file],runId:id,queueId:null,commitSha:state==='ready'?'a'.repeat(40):null,previousSha:'b'.repeat(40)});
const overview:RepositoryOverview={repositoryKey:'fixture',repositoryName:'private-fixture/radio',targetBranch:'main',targetSha:'b'.repeat(40),acceptedSha:'a'.repeat(40),hasHiddenWork:false,changes:[row('a','Fix artwork loading','ready','client/artwork.ts'),row('b','Improve offline playback','ready','client/offline.ts'),row('c','Add a welcome message','working','server/welcome.ts'),row('d','Older audio experiment','stopped','client/experiment.ts')]};
// Disposable browser gateway only. No repository or production server is contacted.
window.fetch=async(input,init)=>{
  const path=new URL(String(input),location.origin).pathname, body=JSON.parse(String(init?.body??'{}'));
  if(path.endsWith('/repository-changes')) return Response.json(overview);
  const preview=(mode:RepositoryReleaseMode)=>({mode,token:`preview-${mode}`,targetBranch:'main',targetSha:overview.targetSha,included:overview.changes.filter(row=>mode==='all'||row.state==='ready'),excluded:overview.changes.filter(row=>mode==='ready'&&row.state!=='ready')});
  if(path.endsWith('/preview')) return Response.json(preview(body.mode));
  if(path.endsWith('/repository-releases')) {const choice=preview(body.mode);overview.release={...choice,id:'fixture-release',state:body.mode==='ready'?'confirmed':'waiting',createdAt:Date.now(),commitSha:body.mode==='ready'?'a'.repeat(40):null,message:body.mode==='ready'?'On GitHub. Deployment has not been verified.':'Waiting for “Add a welcome message” and “Older audio experiment” to finish and pass checks. This release will continue automatically.'};if(body.mode==='ready')overview.changes=choice.excluded;return Response.json(overview.release,{status:202});}
  if(path.endsWith('/cancel')) {overview.release=null;return Response.json({ok:true},{status:202});}
  throw new Error(`Unexpected fixture request ${path}`);
};
